CREATE OR REPLACE FUNCTION private.cleanup_expired_timetable_invites_v1()
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  deleted_count bigint;
begin
  delete from public.timetable_invites
  where expires_at <= now();

  get diagnostics deleted_count = row_count;
  return deleted_count;
end;
$function$

CREATE OR REPLACE FUNCTION private.community_poll_summary_v1_impl(p_poll_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  current_profile_id uuid := public.current_profile_id();
  target_poll public.community_polls%rowtype;
begin
  select *
  into target_poll
  from public.community_polls polls
  where polls.id = p_poll_id
    and (
      polls.status = 'published'
      or public.can_use_profile(polls.author_id)
    );

  if not found then
    return null;
  end if;

  return private.community_poll_json_v2(target_poll, current_profile_id, false);
end;
$function$

CREATE OR REPLACE FUNCTION private.create_community_poll_v1_impl(p_question text, p_detail text DEFAULT NULL::text, p_options text[] DEFAULT ARRAY[]::text[], p_closes_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  current_profile_id uuid := public.current_profile_id();
  normalized_question text := nullif(btrim(coalesce(p_question, '')), '');
  normalized_detail text := nullif(btrim(coalesce(p_detail, '')), '');
  normalized_options text[] := array[]::text[];
  option_text text;
  created_poll_id uuid;
  option_index integer := 0;
begin
  if current_profile_id is null then
    raise exception 'COMMUNITY_PROFILE_REQUIRED';
  end if;

  if not exists (
    select 1
    from public.profiles
    where profiles.id = current_profile_id
      and profiles.is_profile_complete = true
      and nullif(btrim(profiles.nickname), '') is not null
  ) then
    raise exception 'PROFILE_COMPLETION_REQUIRED';
  end if;

  if not public.has_accepted_community_terms(public.community_latest_terms_version()) then
    raise exception 'COMMUNITY_TERMS_REQUIRED';
  end if;

  if public.is_profile_muted(current_profile_id) then
    raise exception 'COMMUNITY_USER_MUTED';
  end if;

  if normalized_question is null or char_length(normalized_question) > 120 then
    raise exception 'COMMUNITY_POLL_INVALID';
  end if;

  if normalized_detail is not null and char_length(normalized_detail) > 500 then
    raise exception 'COMMUNITY_POLL_INVALID';
  end if;

  if p_closes_at is not null and p_closes_at <= now() then
    raise exception 'COMMUNITY_POLL_INVALID';
  end if;

  foreach option_text in array coalesce(p_options, array[]::text[]) loop
    option_text := nullif(btrim(coalesce(option_text, '')), '');
    if option_text is not null then
      if char_length(option_text) > 80 then
        raise exception 'COMMUNITY_POLL_INVALID';
      end if;
      normalized_options := array_append(normalized_options, option_text);
    end if;
  end loop;

  if coalesce(array_length(normalized_options, 1), 0) < 2
     or coalesce(array_length(normalized_options, 1), 0) > 6 then
    raise exception 'COMMUNITY_POLL_INVALID';
  end if;

  insert into public.community_polls (author_id, question, detail, closes_at, status)
  values (current_profile_id, normalized_question, normalized_detail, p_closes_at, 'pending_review')
  returning id into created_poll_id;

  foreach option_text in array normalized_options loop
    insert into public.community_poll_options (poll_id, text, sort_order)
    values (created_poll_id, option_text, option_index);
    option_index := option_index + 1;
  end loop;

  return private.community_poll_summary_v1_impl(created_poll_id);
end;
$function$

CREATE OR REPLACE FUNCTION private.guard_community_post_status_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.status is not distinct from old.status then
    return new;
  end if;

  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.status = 'deleted' then
    return new;
  end if;

  if old.status = 'pending_review'
     and new.status = 'published'
     and current_setting('leafy.community_publish_validated', true) = 'on' then
    return new;
  end if;

  raise exception 'COMMUNITY_POST_STATUS_TRANSITION_FORBIDDEN';
end;
$function$

CREATE OR REPLACE FUNCTION private.insert_community_interaction_notification_v1(p_recipient_id uuid, p_actor_id uuid, p_post_id uuid, p_comment_id uuid, p_type text, p_title text, p_body text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  created_notification_id uuid;
  recipient_muted boolean := false;
  post_campus_id text;
begin
  if p_recipient_id is null or p_recipient_id = p_actor_id then
    return null;
  end if;
  if p_actor_id is distinct from public.current_community_profile_id() then
    raise exception 'COMMUNITY_NOTIFICATION_ACTOR_INVALID';
  end if;
  if p_type not in ('comment', 'like') then
    raise exception 'COMMUNITY_NOTIFICATION_TYPE_INVALID';
  end if;

  select campus_id into post_campus_id
  from public.posts
  where id = p_post_id and status = 'published';

  if post_campus_id is null
     or post_campus_id <> public.current_profile_campus_id()
     or not exists (
       select 1 from public.profiles
       where id = p_recipient_id and community_campus_id = post_campus_id
     ) then
    raise exception 'COMMUNITY_NOTIFICATION_TARGET_INVALID';
  end if;

  select coalesce(muted_all, false) into recipient_muted
  from public.community_notification_settings
  where user_id = p_recipient_id;

  if coalesce(recipient_muted, false) then
    return null;
  end if;

  insert into public.community_notifications (
    recipient_id, actor_id, post_id, comment_id, type, title, body
  ) values (
    p_recipient_id,
    p_actor_id,
    p_post_id,
    p_comment_id,
    p_type,
    left(btrim(p_title), 160),
    nullif(left(btrim(coalesce(p_body, '')), 500), '')
  )
  returning id into created_notification_id;

  return created_notification_id;
end;
$function$

CREATE OR REPLACE FUNCTION private.invoke_community_media_cleanup_v1()
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  project_url text;
  cleanup_secret text;
  request_id bigint;
begin
  delete from private.community_comment_like_requests
  where created_at < now() - interval '7 days';

  select decrypted_secret into project_url
  from vault.decrypted_secrets
  where name = 'community_cleanup_project_url'
  limit 1;

  select decrypted_secret into cleanup_secret
  from vault.decrypted_secrets
  where name = 'community_media_cleanup_secret'
  limit 1;

  if nullif(btrim(project_url), '') is null
     or nullif(btrim(cleanup_secret), '') is null then
    raise exception 'COMMUNITY_MEDIA_CLEANUP_VAULT_SECRETS_REQUIRED';
  end if;

  select net.http_post(
    url := rtrim(project_url, '/') || '/functions/v1/community-media-cleanup',
    headers := jsonb_build_object(
      'x-cleanup-secret', cleanup_secret,
      'Content-Type', 'application/json'
    ),
    body := '{}'::jsonb,
    timeout_milliseconds := 30000
  ) into request_id;
  return request_id;
end;
$function$

CREATE OR REPLACE FUNCTION private.my_authored_community_polls_v1_impl(p_limit integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  current_profile_id uuid := public.current_profile_id();
  safe_limit integer := greatest(1, least(coalesce(p_limit, 30), 50));
  result jsonb;
begin
  if current_profile_id is null then
    raise exception 'COMMUNITY_PROFILE_REQUIRED';
  end if;

  select coalesce(jsonb_agg(
    private.community_poll_json_v2(polls, current_profile_id, false)
    order by polls.created_at desc
  ), '[]'::jsonb)
  into result
  from (
    select *
    from public.community_polls
    where author_id = current_profile_id
    order by created_at desc
    limit safe_limit
  ) polls;

  return result;
end;
$function$

CREATE OR REPLACE FUNCTION private.my_voted_community_polls_v1_impl(p_limit integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  current_profile_id uuid := public.current_profile_id();
  safe_limit integer := greatest(1, least(coalesce(p_limit, 30), 50));
  result jsonb;
begin
  if current_profile_id is null then
    raise exception 'COMMUNITY_PROFILE_REQUIRED';
  end if;

  select coalesce(jsonb_agg(
    private.community_poll_json_v2(polls, current_profile_id, polls.status = 'hidden')
    order by votes.updated_at desc
  ), '[]'::jsonb)
  into result
  from (
    select *
    from public.community_poll_votes
    where user_id = current_profile_id
    order by updated_at desc
    limit safe_limit
  ) votes
  join public.community_polls polls on polls.id = votes.poll_id
  where polls.status <> 'deleted'
    and (polls.status <> 'hidden' or polls.author_id <> current_profile_id);

  return result;
end;
$function$

CREATE OR REPLACE FUNCTION private.posts_category_max_8_chars_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if new.category is not null and char_length(btrim(new.category)) > 8 then
    raise exception 'Post category must be 8 characters or fewer.';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.request_delete_community_poll_v1_impl(p_poll_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  current_profile_id uuid := public.current_profile_id();
  normalized_reason text := nullif(btrim(coalesce(p_reason, '')), '');
  target_poll public.community_polls%rowtype;
begin
  if current_profile_id is null then
    raise exception 'COMMUNITY_PROFILE_REQUIRED';
  end if;

  if normalized_reason is not null and char_length(normalized_reason) > 300 then
    raise exception 'COMMUNITY_POLL_INVALID';
  end if;

  select *
  into target_poll
  from public.community_polls
  where id = p_poll_id
    and author_id = current_profile_id
  for update;

  if not found or target_poll.status = 'deleted' then
    raise exception 'COMMUNITY_POLL_NOT_FOUND';
  end if;

  if target_poll.deletion_status = 'pending' then
    raise exception 'COMMUNITY_POLL_DELETION_PENDING';
  end if;

  update public.community_polls
  set
    deletion_status = 'pending',
    deletion_requested_at = now(),
    deletion_reason = normalized_reason,
    deletion_reviewed_at = null,
    deletion_reviewed_by = null,
    deletion_review_reason = null
  where id = p_poll_id
  returning * into target_poll;

  return private.community_poll_summary_v1_impl(target_poll.id);
end;
$function$

CREATE OR REPLACE FUNCTION private.set_community_media_retention()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.status = 'hidden' then
    new.media_cleanup_hold := true;
  elsif old.status = 'hidden' and new.status in ('published', 'deleted') then
    new.media_cleanup_hold := false;
  end if;

  if new.status = 'deleted' and old.status is distinct from 'deleted' then
    new.media_purge_after := coalesce(new.media_purge_after, now() + interval '30 days');
  elsif new.status = 'published' then
    new.media_purge_after := null;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.toggle_post_favorite_v1_impl(p_post_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  current_profile_id uuid := public.current_profile_id();
  target_post public.posts%rowtype;
begin
  if current_profile_id is null then
    raise exception 'COMMUNITY_PROFILE_REQUIRED';
  end if;

  if not exists (
    select 1
    from public.profiles
    where profiles.id = current_profile_id
      and profiles.is_profile_complete = true
      and nullif(btrim(profiles.nickname), '') is not null
  ) then
    raise exception 'PROFILE_COMPLETION_REQUIRED';
  end if;

  if not public.has_accepted_community_terms(public.community_latest_terms_version()) then
    raise exception 'COMMUNITY_TERMS_REQUIRED';
  end if;

  select *
  into target_post
  from public.posts
  where id = p_post_id
    and status = 'published';

  if not found then
    raise exception 'COMMUNITY_POST_NOT_FOUND';
  end if;

  if exists (
    select 1
    from public.community_blocks blocks
    where blocks.blocker_id = current_profile_id
      and blocks.blocked_id = target_post.author_id
  ) then
    raise exception 'COMMUNITY_POST_NOT_FOUND';
  end if;

  if exists (
    select 1
    from public.post_favorites
    where post_id = p_post_id
      and user_id = current_profile_id
  ) then
    delete from public.post_favorites
    where post_id = p_post_id
      and user_id = current_profile_id;
  else
    insert into public.post_favorites (post_id, user_id, created_at)
    values (p_post_id, current_profile_id, now())
    on conflict (post_id, user_id) do nothing;
  end if;

  return private.community_post_summary_v1_impl(p_post_id);
end;
$function$

CREATE OR REPLACE FUNCTION private.toggle_post_like_v1_impl(p_post_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  current_profile_id uuid := public.current_profile_id();
  target_post public.posts%rowtype;
  did_create boolean := false;
  inserted_rows integer := 0;
begin
  if current_profile_id is null then
    raise exception 'COMMUNITY_PROFILE_REQUIRED';
  end if;

  if not exists (
    select 1
    from public.profiles
    where profiles.id = current_profile_id
      and profiles.is_profile_complete = true
      and nullif(btrim(profiles.nickname), '') is not null
  ) then
    raise exception 'PROFILE_COMPLETION_REQUIRED';
  end if;

  if not public.has_accepted_community_terms(public.community_latest_terms_version()) then
    raise exception 'COMMUNITY_TERMS_REQUIRED';
  end if;

  select *
  into target_post
  from public.posts
  where id = p_post_id
    and status = 'published';

  if not found then
    raise exception 'COMMUNITY_POST_NOT_FOUND';
  end if;

  if target_post.author_id = current_profile_id then
    raise exception 'CANNOT_LIKE_OWN_POST';
  end if;

  if exists (
    select 1
    from public.community_blocks blocks
    where blocks.blocker_id = current_profile_id
      and blocks.blocked_id = target_post.author_id
  ) then
    raise exception 'COMMUNITY_POST_NOT_FOUND';
  end if;

  if exists (
    select 1
    from public.post_likes
    where post_id = p_post_id
      and user_id = current_profile_id
  ) then
    delete from public.post_likes
    where post_id = p_post_id
      and user_id = current_profile_id;
  else
    insert into public.post_likes (post_id, user_id, created_at)
    values (p_post_id, current_profile_id, now())
    on conflict (post_id, user_id) do nothing;
    get diagnostics inserted_rows = row_count;
    did_create := inserted_rows > 0;
  end if;

  if did_create and target_post.author_id <> current_profile_id then
    perform public.create_community_notification(
      target_post.author_id,
      current_profile_id,
      p_post_id,
      null,
      'like',
      coalesce((
        select nullif(btrim(nickname), '')
        from public.profiles
        where id = current_profile_id
      ), '北林同学') || ' 点赞了你的帖子',
      target_post.title
    );
  end if;

  return private.community_post_summary_v1_impl(p_post_id);
end;
$function$

CREATE OR REPLACE FUNCTION private.try_publish_community_post_media_v1(p_post_id uuid)
 RETURNS posts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  post_record public.posts%rowtype;
  image_count integer;
  attachment_count integer;
begin
  select * into post_record
  from public.posts where id = p_post_id
  for update;

  if post_record.id is null or post_record.status <> 'pending_review' then
    return post_record;
  end if;

  select count(*)::integer into image_count
  from public.post_images where post_id = p_post_id;
  select count(*)::integer into attachment_count
  from public.post_attachments where post_id = p_post_id;

  if post_record.expected_image_count is not null
     and image_count = post_record.expected_image_count
     and attachment_count = coalesce(post_record.expected_attachment_count, 0)
     and image_count + attachment_count > 0 then
    perform set_config('leafy.community_publish_validated', 'on', true);
    update public.posts
    set
      status = 'published',
      image_upload_completed_at = case
        when image_count = coalesce(expected_image_count, image_count) then coalesce(image_upload_completed_at, now())
        else image_upload_completed_at
      end,
      attachment_upload_completed_at = case
        when attachment_count = expected_attachment_count then coalesce(attachment_upload_completed_at, now())
        else attachment_upload_completed_at
      end,
      updated_at = now()
    where id = p_post_id and status = 'pending_review'
    returning * into post_record;
  end if;
  return post_record;
end;
$function$

CREATE OR REPLACE FUNCTION private.vote_community_poll_v1_impl(p_poll_id uuid, p_option_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  current_profile_id uuid := public.current_profile_id();
  target_poll public.community_polls%rowtype;
  existing_option_id uuid;
begin
  if current_profile_id is null then
    raise exception 'COMMUNITY_PROFILE_REQUIRED';
  end if;

  if not exists (
    select 1
    from public.profiles
    where profiles.id = current_profile_id
      and profiles.is_profile_complete = true
      and nullif(btrim(profiles.nickname), '') is not null
  ) then
    raise exception 'PROFILE_COMPLETION_REQUIRED';
  end if;

  if not public.has_accepted_community_terms(public.community_latest_terms_version()) then
    raise exception 'COMMUNITY_TERMS_REQUIRED';
  end if;

  select *
  into target_poll
  from public.community_polls
  where id = p_poll_id
    and status = 'published'
  for update;

  if not found then
    raise exception 'COMMUNITY_POLL_NOT_FOUND';
  end if;

  if target_poll.closes_at is not null and target_poll.closes_at <= now() then
    raise exception 'COMMUNITY_POLL_CLOSED';
  end if;

  if not exists (
    select 1
    from public.community_poll_options
    where id = p_option_id
      and poll_id = p_poll_id
  ) then
    raise exception 'COMMUNITY_POLL_OPTION_NOT_FOUND';
  end if;

  select option_id
  into existing_option_id
  from public.community_poll_votes
  where poll_id = p_poll_id
    and user_id = current_profile_id
  for update;

  if existing_option_id = p_option_id then
    return private.community_poll_summary_v1_impl(p_poll_id);
  end if;

  if existing_option_id is not null then
    update public.community_poll_options
    set vote_count = greatest(vote_count - 1, 0)
    where id = existing_option_id;
  else
    update public.community_polls
    set total_vote_count = total_vote_count + 1
    where id = p_poll_id;
  end if;

  update public.community_poll_options
  set vote_count = vote_count + 1
  where id = p_option_id;

  insert into public.community_poll_votes (poll_id, option_id, user_id, created_at, updated_at)
  values (p_poll_id, p_option_id, current_profile_id, now(), now())
  on conflict (poll_id, user_id) do update
  set
    option_id = excluded.option_id,
    updated_at = now();

  return private.community_poll_summary_v1_impl(p_poll_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.accept_community_terms(p_terms_version text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  current_profile_id uuid := public.current_community_profile_id();
  accepted_version text := coalesce(nullif(btrim(p_terms_version), ''), public.community_latest_terms_version());
begin
  if current_profile_id is null then
    raise exception 'COMMUNITY_PROFILE_REQUIRED';
  end if;

  if not exists (select 1 from public.profiles where id = current_profile_id) then
    raise exception 'COMMUNITY_PROFILE_REQUIRED';
  end if;

  insert into public.community_terms_acceptances (user_id, terms_version, accepted_at)
  values (current_profile_id, accepted_version, now())
  on conflict (user_id, terms_version)
  do update set accepted_at = excluded.accepted_at;
end;
$function$

CREATE OR REPLACE FUNCTION public.accept_timetable_invite(p_code text)
 RETURNS TABLE(id uuid, owner_id uuid, semester_id text, courses jsonb, course_count integer, published_at timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  actor_profile_id uuid;
  actor_campus_id text;
  normalized_code text;
  target_invite public.timetable_invites%rowtype;
  target_snapshot public.timetable_snapshots%rowtype;
begin
  actor_profile_id := public.current_profile_id();
  actor_campus_id := public.current_profile_campus_id();
  if actor_profile_id is null or actor_campus_id is null then
    raise exception 'MISSING_PROFILE';
  end if;

  normalized_code := public.normalize_timetable_invite_code(p_code);
  if char_length(normalized_code) <> 12 then
    raise exception 'INVALID_INVITE_CODE';
  end if;

  select *
  into target_invite
  from public.timetable_invites invites
  where invites.campus_id = actor_campus_id
    and invites.code_hash = public.hash_timetable_invite_code(normalized_code)
  for update;

  if target_invite.id is null then
    raise exception 'INVALID_INVITE_CODE';
  end if;

  if target_invite.expires_at <= now() then
    raise exception 'INVITE_EXPIRED';
  end if;

  if target_invite.accepted_by is not null then
    raise exception 'INVITE_USED';
  end if;

  if target_invite.owner_id = actor_profile_id then
    raise exception 'INVITE_SELF';
  end if;

  select *
  into target_snapshot
  from public.timetable_snapshots snapshots
  where snapshots.owner_id = target_invite.owner_id
    and snapshots.semester_id = target_invite.semester_id
    and snapshots.campus_id = actor_campus_id
  limit 1;

  if target_snapshot.id is null then
    raise exception 'TIMETABLE_NOT_PUBLISHED';
  end if;

  insert into public.timetable_share_members (
    campus_id,
    owner_id,
    viewer_id,
    revoked_at
  )
  values (
    actor_campus_id,
    target_invite.owner_id,
    actor_profile_id,
    null
  )
  on conflict on constraint timetable_share_members_owner_viewer_unique do update
  set
    campus_id = excluded.campus_id,
    revoked_at = null,
    updated_at = now();

  update public.timetable_invites
  set
    accepted_by = actor_profile_id,
    accepted_at = now()
  where timetable_invites.id = target_invite.id
    and timetable_invites.campus_id = actor_campus_id;

  return query
  select
    target_snapshot.id,
    target_snapshot.owner_id,
    target_snapshot.semester_id,
    target_snapshot.courses,
    target_snapshot.course_count,
    target_snapshot.published_at,
    target_snapshot.created_at,
    target_snapshot.updated_at;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_approve_campus_request_v1(p_request_id uuid, p_admin_id uuid, p_campus_id text DEFAULT NULL::text, p_display_name text DEFAULT NULL::text, p_short_name text DEFAULT NULL::text, p_new_campus_id text DEFAULT NULL::text, p_admin_note text DEFAULT NULL::text)
 RETURNS campus_membership_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  request_row public.campus_membership_requests%rowtype;
  target_campus_id text;
  target_display_name text;
  target_normalized_name text;
begin
  select *
  into request_row
  from public.campus_membership_requests
  where id = p_request_id
  for update;

  if request_row.id is null then
    raise exception 'COMMUNITY_REQUEST_NOT_FOUND' using errcode = 'P0001';
  end if;
  if request_row.status <> 'pending' then
    raise exception 'ADMIN_CAMPUS_REQUEST_ALREADY_REVIEWED' using errcode = 'P0001';
  end if;

  if request_row.request_type = 'school_change' then
    target_campus_id := request_row.requested_campus_id;
  elsif nullif(lower(btrim(coalesce(p_campus_id, ''))), '') is not null
    and lower(btrim(p_campus_id)) <> 'new' then
    target_campus_id := lower(btrim(p_campus_id));
  else
    target_display_name := coalesce(nullif(btrim(p_display_name), ''), request_row.school_name);
    target_normalized_name := public.normalize_school_name(target_display_name);
    if target_normalized_name in (
      public.normalize_school_name('北京林业大学'),
      public.normalize_school_name('北林')
    ) then
      raise exception 'ADMIN_INVALID_CAMPUS_TARGET' using errcode = '22023';
    end if;

    select campuses.id
    into target_campus_id
    from public.campuses
    where campuses.normalized_name = target_normalized_name;

    if target_campus_id is null then
      target_campus_id := lower(btrim(coalesce(
        nullif(p_new_campus_id, ''),
        'campus-' || replace(request_row.id::text, '-', '')
      )));
      insert into public.campuses (
        id,
        display_name,
        short_name,
        connector_kind,
        status,
        normalized_name,
        is_community_enabled,
        is_system
      )
      values (
        target_campus_id,
        target_display_name,
        coalesce(nullif(btrim(p_short_name), ''), left(target_display_name, 6)),
        'custom',
        'active',
        target_normalized_name,
        true,
        false
      );
    end if;
  end if;

  if target_campus_id is null
    or target_campus_id = 'general'
    or (request_row.request_type <> 'school_change' and target_campus_id = 'bjfu') then
    raise exception 'ADMIN_INVALID_CAMPUS_TARGET' using errcode = '22023';
  end if;

  if not exists (
    select 1
    from public.campuses
    where campuses.id = target_campus_id
      and campuses.status = 'active'
      and campuses.is_community_enabled
  ) then
    raise exception 'COMMUNITY_CAMPUS_NOT_FOUND' using errcode = 'P0001';
  end if;

  return public.approve_campus_membership_request(
    request_row.id,
    target_campus_id,
    p_admin_id,
    p_admin_note
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_approve_catalog_suggestion_v1(p_suggestion_id uuid, p_admin_id uuid, p_admin_note text DEFAULT NULL::text)
 RETURNS catalog_suggestions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  suggestion public.catalog_suggestions%rowtype;
  target_teacher_id bigint;
  target_course_id bigint;
  target_dish_id bigint;
begin
  select * into suggestion from public.catalog_suggestions
  where id = p_suggestion_id for update;
  if suggestion.id is null then raise exception 'ADMIN_CATALOG_SUGGESTION_NOT_FOUND' using errcode = 'P0001'; end if;
  if suggestion.status <> 'open' then raise exception 'ADMIN_CATALOG_SUGGESTION_ALREADY_REVIEWED' using errcode = 'P0001'; end if;
  if nullif(btrim(suggestion.campus_id), '') is null then raise exception 'ADMIN_CAMPUS_REQUIRED' using errcode = '22023'; end if;
  if suggestion.user_id is not null and not exists (
    select 1 from public.profiles where id = suggestion.user_id
      and community_campus_id = suggestion.campus_id and community_access_status = 'approved'
  ) then
    raise exception 'ADMIN_CATALOG_SUGGESTION_CAMPUS_MISMATCH' using errcode = 'P0001';
  end if;

  if suggestion.suggestion_type = 'teacher' then
    select id into target_teacher_id from public.teachers
    where campus_id = suggestion.campus_id and lower(btrim(name)) = lower(btrim(suggestion.name))
      and lower(btrim(unit)) = lower(btrim(suggestion.unit))
    order by id limit 1 for update;
    if target_teacher_id is null then
      insert into public.teachers(campus_id, name, unit, status)
      values (suggestion.campus_id, btrim(suggestion.name), btrim(suggestion.unit), 'published')
      on conflict do nothing returning id into target_teacher_id;
      if target_teacher_id is null then
        select id into target_teacher_id from public.teachers
        where campus_id = suggestion.campus_id and lower(btrim(name)) = lower(btrim(suggestion.name))
          and lower(btrim(unit)) = lower(btrim(suggestion.unit)) order by id limit 1 for update;
      end if;
    end if;
    update public.teachers set status = 'published' where id = target_teacher_id and status <> 'published';
    if suggestion.initial_stars is not null and suggestion.user_id is not null then
      insert into public.teacher_ratings(teacher_id, user_id, stars)
      values (target_teacher_id, suggestion.user_id, suggestion.initial_stars)
      on conflict (teacher_id, user_id) do update set stars = excluded.stars;
    end if;
  elsif suggestion.suggestion_type = 'course' then
    select id into target_course_id from public.course_catalog
    where campus_id = suggestion.campus_id and lower(btrim(name)) = lower(btrim(suggestion.name))
      and lower(btrim(unit)) = lower(btrim(suggestion.unit))
      and lower(btrim(category)) = lower(btrim(coalesce(suggestion.category, '公选课')))
    order by id limit 1 for update;
    if target_course_id is null then
      insert into public.course_catalog(campus_id, name, unit, category, credit, status)
      values (suggestion.campus_id, btrim(suggestion.name), btrim(suggestion.unit),
        coalesce(nullif(btrim(suggestion.category), ''), '公选课'), coalesce(suggestion.credit, 0), 'published')
      on conflict do nothing returning id into target_course_id;
      if target_course_id is null then
        select id into target_course_id from public.course_catalog
        where campus_id = suggestion.campus_id and lower(btrim(name)) = lower(btrim(suggestion.name))
          and lower(btrim(unit)) = lower(btrim(suggestion.unit))
          and lower(btrim(category)) = lower(btrim(coalesce(suggestion.category, '公选课')))
        order by id limit 1 for update;
      end if;
    end if;
    update public.course_catalog set status = 'published', credit = coalesce(suggestion.credit, credit)
    where id = target_course_id and (status <> 'published' or suggestion.credit is not null);
    if suggestion.initial_stars is not null and suggestion.user_id is not null then
      insert into public.course_ratings(course_id, user_id, stars)
      values (target_course_id, suggestion.user_id, suggestion.initial_stars)
      on conflict (course_id, user_id) do update set stars = excluded.stars;
    end if;
  elsif suggestion.suggestion_type = 'dish' then
    select id into target_dish_id from public.dish_catalog
    where campus_id = suggestion.campus_id and lower(btrim(name)) = lower(btrim(suggestion.name))
      and lower(btrim(location)) = lower(btrim(suggestion.unit))
    order by id limit 1 for update;
    if target_dish_id is null then
      insert into public.dish_catalog(campus_id, name, location, status)
      values (suggestion.campus_id, btrim(suggestion.name), btrim(suggestion.unit), 'published')
      on conflict do nothing returning id into target_dish_id;
      if target_dish_id is null then
        select id into target_dish_id from public.dish_catalog
        where campus_id = suggestion.campus_id and lower(btrim(name)) = lower(btrim(suggestion.name))
          and lower(btrim(location)) = lower(btrim(suggestion.unit)) order by id limit 1 for update;
      end if;
    end if;
    update public.dish_catalog set status = 'published' where id = target_dish_id and status <> 'published';
    if suggestion.initial_stars is not null and suggestion.user_id is not null then
      insert into public.dish_ratings(dish_id, user_id, stars)
      values (target_dish_id, suggestion.user_id, suggestion.initial_stars)
      on conflict (dish_id, user_id) do update set stars = excluded.stars;
    end if;
  else
    raise exception 'ADMIN_INVALID_CATALOG_SUGGESTION_TYPE' using errcode = '22023';
  end if;

  update public.catalog_suggestions set
    status = 'approved', approved_teacher_id = target_teacher_id,
    approved_course_id = target_course_id, approved_dish_id = target_dish_id,
    admin_note = nullif(btrim(coalesce(p_admin_note, '')), ''),
    reviewed_by = p_admin_id, reviewed_at = now()
  where id = suggestion.id returning * into suggestion;
  return suggestion;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_approve_postgraduate_suggestion_v1(p_suggestion_id uuid, p_admin_id uuid, p_summary text DEFAULT NULL::text, p_admin_note text DEFAULT NULL::text)
 RETURNS postgraduate_source_suggestions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  suggestion public.postgraduate_source_suggestions%rowtype;
  source_id uuid;
begin
  select * into suggestion from public.postgraduate_source_suggestions
  where id = p_suggestion_id for update;
  if suggestion.id is null then raise exception 'ADMIN_POSTGRADUATE_SUGGESTION_NOT_FOUND' using errcode = 'P0001'; end if;
  if suggestion.status <> 'open' then raise exception 'ADMIN_POSTGRADUATE_SUGGESTION_ALREADY_REVIEWED' using errcode = 'P0001'; end if;
  insert into public.postgraduate_sources(
    title, summary, source_url, source_kind, trust_level, school, unit, major,
    exam_year, status, verified_at, created_by, updated_by
  ) values (
    suggestion.title, coalesce(p_summary, suggestion.note, ''), suggestion.source_url,
    suggestion.source_kind, 'verified_user', suggestion.school, suggestion.unit,
    suggestion.major, suggestion.exam_year, 'published', now(), p_admin_id, p_admin_id
  ) returning id into source_id;
  update public.postgraduate_source_suggestions set
    status = 'approved', approved_source_id = source_id,
    admin_note = nullif(btrim(coalesce(p_admin_note, '')), ''),
    reviewed_by = p_admin_id, reviewed_at = now()
  where id = suggestion.id returning * into suggestion;
  return suggestion;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_begin_login_attempt(p_username text, p_ip_address inet, p_at timestamp with time zone DEFAULT now())
 RETURNS TABLE(attempt_id uuid, is_rate_limited boolean, retry_after timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  status record;
  created_id uuid;
begin
  if nullif(btrim(coalesce(p_username, '')), '') is null or p_ip_address is null then
    raise exception 'ADMIN_LOGIN_ATTEMPT_IDENTITY_REQUIRED';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('leafy.admin-login:' || p_ip_address::text, 0));
  select * into status
  from public.admin_login_rate_limit_status(p_username, p_ip_address, p_at);

  if status.is_rate_limited then
    insert into public.admin_login_attempts (username, ip_address, succeeded, error_code, attempted_at)
    values (p_username, p_ip_address, false, 'rate_limited', coalesce(p_at, now()))
    returning id into created_id;
    return query select created_id, true, status.retry_after;
    return;
  end if;

  insert into public.admin_login_attempts (username, ip_address, succeeded, attempted_at)
  values (p_username, p_ip_address, false, coalesce(p_at, now()))
  returning id into created_id;

  return query select created_id, false, null::timestamptz;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_cleanup_login_attempts(p_before timestamp with time zone DEFAULT (now() - '90 days'::interval))
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  deleted_count bigint;
begin
  if p_before is null then
    raise exception 'ADMIN_LOGIN_ATTEMPTS_CLEANUP_BOUNDARY_REQUIRED';
  end if;

  delete from public.admin_login_attempts
  where attempted_at < p_before;

  get diagnostics deleted_count = row_count;
  return deleted_count;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_create_account(p_username text, p_password text, p_display_name text DEFAULT NULL::text, p_role text DEFAULT 'super_admin'::text, p_created_by uuid DEFAULT NULL::uuid)
 RETURNS TABLE(id uuid, username text, display_name text, role text, active boolean, last_login_at timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  normalized_username text;
  normalized_display_name text;
  normalized_role text;
  created_account_id uuid;
begin
  normalized_username := lower(btrim(coalesce(p_username, '')));
  normalized_display_name := coalesce(nullif(btrim(p_display_name), ''), normalized_username);
  normalized_role := coalesce(nullif(btrim(p_role), ''), 'super_admin');

  if normalized_username !~ '^[a-z0-9_.-]{3,64}$' then
    raise exception 'ADMIN_INVALID_USERNAME';
  end if;

  if char_length(coalesce(p_password, '')) < 8 then
    raise exception 'ADMIN_PASSWORD_TOO_SHORT';
  end if;

  if normalized_role not in ('super_admin', 'operator', 'viewer') then
    raise exception 'ADMIN_INVALID_ROLE';
  end if;

  if exists (select 1 from public.admin_accounts) then
    if not exists (
      select 1
      from public.admin_accounts
      where admin_accounts.id = p_created_by
        and admin_accounts.role = 'super_admin'
        and admin_accounts.active = true
    ) then
      raise exception 'ADMIN_SUPER_ADMIN_REQUIRED';
    end if;
  end if;

  insert into public.admin_accounts (
    username,
    password_hash,
    display_name,
    role,
    created_by
  )
  values (
    normalized_username,
    crypt(p_password, gen_salt('bf', 12)),
    normalized_display_name,
    normalized_role,
    p_created_by
  )
  returning admin_accounts.id into created_account_id;

  return query
  select
    a.id,
    a.username,
    a.display_name,
    a.role,
    a.active,
    a.last_login_at,
    a.created_at,
    a.updated_at
  from public.admin_accounts a
  where a.id = created_account_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_login(p_username text, p_password text, p_expires_in_hours integer DEFAULT 12)
 RETURNS TABLE(token text, expires_at timestamp with time zone, admin_id uuid, username text, display_name text, role text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  account public.admin_accounts%rowtype;
  raw_token text;
  session_hash text;
  session_expires_at timestamptz;
begin
  select *
  into account
  from public.admin_accounts
  where admin_accounts.username = lower(btrim(coalesce(p_username, '')))
    and admin_accounts.active = true;

  if account.id is null
    or account.password_hash <> crypt(coalesce(p_password, ''), account.password_hash)
  then
    raise exception 'ADMIN_INVALID_CREDENTIALS';
  end if;

  raw_token := encode(gen_random_bytes(32), 'hex');
  session_hash := encode(digest(raw_token, 'sha256'), 'hex');
  session_expires_at := now() + make_interval(hours => greatest(1, least(coalesce(p_expires_in_hours, 12), 72)));

  insert into public.admin_sessions (
    token_hash,
    admin_id,
    expires_at
  )
  values (
    session_hash,
    account.id,
    session_expires_at
  );

  update public.admin_accounts
  set last_login_at = now()
  where admin_accounts.id = account.id;

  return query
  select
    raw_token,
    session_expires_at,
    account.id,
    account.username,
    account.display_name,
    account.role;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_moderate_posts_v1(p_post_ids uuid[], p_status text, p_reason text, p_admin_id uuid)
 RETURNS SETOF posts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if p_status not in ('published', 'hidden') then
    raise exception 'ADMIN_INVALID_POST_STATUS' using errcode = '22023';
  end if;
  if cardinality(p_post_ids) = 1 then
    if not exists (select 1 from public.posts where id = p_post_ids[1]) then
      raise exception 'ADMIN_POST_NOT_FOUND' using errcode = 'P0001';
    end if;
    if exists (select 1 from public.posts where id = p_post_ids[1] and status = 'deleted') then
      raise exception 'ADMIN_POST_DELETED' using errcode = 'P0001';
    end if;
  end if;
  if p_status = 'published'
     and exists (
       select 1 from public.posts
       where id = any(p_post_ids) and status = 'pending_review'
     ) then
    raise exception 'ADMIN_PENDING_POST_REQUIRES_RETRY' using errcode = '23514';
  end if;
  if p_status = 'hidden' then
    update public.community_post_pins
    set status = 'inactive'
    where post_id = any(p_post_ids)
      and status = 'active';
  end if;
  return query update public.posts
  set
    status = p_status,
    moderated_by = p_admin_id,
    moderated_at = now(),
    moderation_reason = case
      when p_status = 'hidden' then coalesce(nullif(btrim(p_reason), ''), 'Hidden by admin')
      else null
    end
  where id = any(p_post_ids)
    and status <> 'deleted'
  returning *;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_pin_post_v1(p_post_id uuid, p_scope text, p_category text, p_priority integer, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone, p_reason text, p_admin_id uuid)
 RETURNS community_post_pins
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  post_row public.posts%rowtype;
  pin_row public.community_post_pins%rowtype;
begin
  select * into post_row from public.posts where id = p_post_id for update;
  if post_row.id is null then raise exception 'ADMIN_POST_NOT_FOUND' using errcode = 'P0001'; end if;
  if post_row.status <> 'published' then raise exception 'ADMIN_POST_NOT_PUBLISHED' using errcode = 'P0001'; end if;
  update public.community_post_pins set status = 'inactive'
  where post_id = p_post_id and scope = p_scope
    and coalesce(category, '') = coalesce(p_category, '') and status = 'active';
  insert into public.community_post_pins(post_id, campus_id, scope, category, priority, starts_at, ends_at, status, reason, created_by)
  values (p_post_id, post_row.campus_id, p_scope, p_category, p_priority, p_starts_at, p_ends_at, 'active', p_reason, p_admin_id)
  returning * into pin_row;
  return pin_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_resolve_moderation_report_v1(p_report_id uuid, p_status text, p_resolution_note text, p_hide_content boolean, p_mute_user boolean, p_muted_until timestamp with time zone, p_muted_reason text, p_admin_id uuid)
 RETURNS community_reports
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  report_row public.community_reports%rowtype;
begin
  select * into report_row from public.community_reports where id = p_report_id for update;
  if report_row.id is null then raise exception 'ADMIN_REPORT_NOT_FOUND' using errcode = 'P0001'; end if;
  if report_row.status not in ('open', 'reviewed') then raise exception 'ADMIN_REPORT_ALREADY_REVIEWED' using errcode = 'P0001'; end if;
  if p_status not in ('reviewed', 'resolved', 'rejected') then raise exception 'ADMIN_INVALID_REPORT_STATUS' using errcode = '22023'; end if;
  if p_hide_content then
    if report_row.target_type = 'post' and report_row.post_id is not null then
      update public.community_post_pins set status = 'inactive' where post_id = report_row.post_id and status = 'active';
      update public.posts set status = 'hidden', moderated_by = p_admin_id, moderated_at = now(), moderation_reason = p_resolution_note
      where id = report_row.post_id and status <> 'deleted';
    elsif report_row.target_type = 'comment' and report_row.comment_id is not null then
      update public.comments set status = 'hidden', moderated_by = p_admin_id, moderated_at = now(), moderation_reason = p_resolution_note
      where id = report_row.comment_id and status <> 'deleted';
    end if;
  end if;
  if p_mute_user and report_row.reported_user_id is not null then
    update public.profiles set muted_until = coalesce(p_muted_until, now() + interval '1 year'),
      muted_reason = coalesce(nullif(btrim(p_muted_reason), ''), 'Community report upheld'),
      muted_by = p_admin_id, muted_at = now()
    where id = report_row.reported_user_id;
  end if;
  update public.community_reports set status = p_status, resolved_by = p_admin_id,
    resolved_at = now(), resolution_note = p_resolution_note
  where id = report_row.id returning * into report_row;
  return report_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_retry_pending_post_publish_v1(p_post_id uuid, p_admin_id uuid)
 RETURNS posts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  post_record public.posts%rowtype;
  attached_image_count integer;
  attached_attachment_count integer;
begin
  select * into post_record
  from public.posts
  where id = p_post_id
  for update;

  if post_record.id is null then
    raise exception 'ADMIN_POST_NOT_FOUND' using errcode = 'P0001';
  end if;
  if post_record.status = 'deleted' then
    raise exception 'ADMIN_POST_DELETED' using errcode = 'P0001';
  end if;
  if post_record.status <> 'pending_review' then
    raise exception 'ADMIN_POST_NOT_PENDING' using errcode = 'P0001';
  end if;

  select count(*)::integer into attached_image_count
  from public.post_images where post_id = p_post_id;
  select count(*)::integer into attached_attachment_count
  from public.post_attachments where post_id = p_post_id;

  if attached_image_count <> coalesce(post_record.expected_image_count, attached_image_count)
     or attached_attachment_count <> post_record.expected_attachment_count
     or attached_image_count + attached_attachment_count = 0 then
    raise exception 'ADMIN_POST_MEDIA_UPLOAD_INCOMPLETE' using errcode = '23514';
  end if;

  perform set_config('leafy.community_publish_validated', 'on', true);
  update public.posts
  set
    status = 'published',
    image_upload_completed_at = coalesce(image_upload_completed_at, now()),
    attachment_upload_completed_at = coalesce(attachment_upload_completed_at, now()),
    moderated_by = p_admin_id,
    moderated_at = now(),
    moderation_reason = null,
    updated_at = now()
  where id = p_post_id
  returning * into post_record;
  return post_record;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_update_account(p_account_id uuid, p_actor_id uuid, p_username text DEFAULT NULL::text, p_password text DEFAULT NULL::text, p_display_name text DEFAULT NULL::text, p_role text DEFAULT NULL::text, p_active boolean DEFAULT NULL::boolean)
 RETURNS TABLE(id uuid, username text, display_name text, role text, active boolean, last_login_at timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  target_account public.admin_accounts%rowtype;
  normalized_username text;
  normalized_display_name text;
  normalized_role text;
  next_active boolean;
  next_role text;
begin
  if not exists (
    select 1
    from public.admin_accounts
    where admin_accounts.id = p_actor_id
      and admin_accounts.role = 'super_admin'
      and admin_accounts.active = true
  ) then
    raise exception 'ADMIN_SUPER_ADMIN_REQUIRED';
  end if;

  select *
  into target_account
  from public.admin_accounts
  where admin_accounts.id = p_account_id
  for update;

  if target_account.id is null then
    raise exception 'ADMIN_ACCOUNT_NOT_FOUND';
  end if;

  normalized_username := case
    when p_username is null then target_account.username
    else lower(btrim(p_username))
  end;
  normalized_display_name := case
    when p_display_name is null then target_account.display_name
    else coalesce(nullif(btrim(p_display_name), ''), normalized_username)
  end;
  normalized_role := case
    when p_role is null then target_account.role
    else btrim(p_role)
  end;
  next_active := coalesce(p_active, target_account.active);
  next_role := normalized_role;

  if normalized_username !~ '^[a-z0-9_.-]{3,64}$' then
    raise exception 'ADMIN_INVALID_USERNAME';
  end if;

  if normalized_role not in ('super_admin', 'operator', 'viewer') then
    raise exception 'ADMIN_INVALID_ROLE';
  end if;

  if p_password is not null and char_length(p_password) < 8 then
    raise exception 'ADMIN_PASSWORD_TOO_SHORT';
  end if;

  if p_account_id = p_actor_id and next_active = false then
    raise exception 'ADMIN_CANNOT_DISABLE_SELF';
  end if;

  if target_account.active = true
    and target_account.role = 'super_admin'
    and (next_active = false or next_role <> 'super_admin')
    and not exists (
      select 1
      from public.admin_accounts
      where admin_accounts.id <> target_account.id
        and admin_accounts.active = true
        and admin_accounts.role = 'super_admin'
    )
  then
    raise exception 'ADMIN_LAST_SUPER_ADMIN';
  end if;

  update public.admin_accounts
  set
    username = normalized_username,
    display_name = normalized_display_name,
    role = normalized_role,
    active = next_active,
    password_hash = case
      when p_password is null then password_hash
      else crypt(p_password, gen_salt('bf', 12))
    end
  where admin_accounts.id = target_account.id;

  return query
  select
    a.id,
    a.username,
    a.display_name,
    a.role,
    a.active,
    a.last_login_at,
    a.created_at,
    a.updated_at
  from public.admin_accounts a
  where a.id = target_account.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.attach_community_post_attachment_v1(p_receipt_id uuid, p_attachment_id uuid, p_sort_order integer)
 RETURNS post_attachments
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  current_profile_id uuid := public.current_community_profile_id();
  receipt private.community_attachment_upload_receipts%rowtype;
  post_record public.posts%rowtype;
  attachment_record public.post_attachments%rowtype;
  attached_count integer;
begin
  if current_profile_id is null then
    raise exception 'COMMUNITY_PROFILE_REQUIRED';
  end if;

  select * into receipt
  from private.community_attachment_upload_receipts
  where id = p_receipt_id
  for update;

  if not found
     or receipt.profile_id <> current_profile_id
     or receipt.auth_user_id <> auth.uid()
     or receipt.consumed_at is not null
     or receipt.expires_at <= now() then
    raise exception 'COMMUNITY_UPLOAD_RECEIPT_INVALID';
  end if;

  select * into post_record
  from public.posts
  where id = receipt.post_id
  for update;

  if post_record.id is null
     or post_record.author_id <> current_profile_id
     or post_record.status <> 'pending_review'
     or p_sort_order < 0
     or p_sort_order >= post_record.expected_attachment_count then
    raise exception 'COMMUNITY_ATTACHMENT_COUNT_MISMATCH';
  end if;

  insert into public.post_attachments (
    id, post_id, path, display_name, content_type, file_extension,
    byte_size, sha256, sort_order
  ) values (
    coalesce(p_attachment_id, gen_random_uuid()),
    receipt.post_id,
    receipt.object_path,
    receipt.display_name,
    receipt.content_type,
    receipt.file_extension,
    receipt.byte_size,
    receipt.sha256,
    p_sort_order
  )
  returning * into attachment_record;

  update private.community_attachment_upload_receipts
  set consumed_at = now()
  where id = receipt.id;

  select count(*)::integer into attached_count
  from public.post_attachments where post_id = receipt.post_id;
  if attached_count > post_record.expected_attachment_count then
    raise exception 'COMMUNITY_ATTACHMENT_COUNT_MISMATCH';
  end if;

  perform private.try_publish_community_post_media_v1(receipt.post_id);
  return attachment_record;
end;
$function$

CREATE OR REPLACE FUNCTION public.attach_community_post_image_v1(p_receipt_id uuid, p_image_id uuid, p_sort_order integer)
 RETURNS post_images
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  current_profile_id uuid := public.current_community_profile_id();
  receipt private.community_upload_receipts%rowtype;
  post_record public.posts%rowtype;
  image_record public.post_images%rowtype;
  attached_image_count integer;
begin
  if current_profile_id is null then
    raise exception 'COMMUNITY_PROFILE_REQUIRED';
  end if;
  select * into receipt
  from private.community_upload_receipts
  where id = p_receipt_id
  for update;
  if not found
     or receipt.profile_id <> current_profile_id
     or receipt.auth_user_id <> auth.uid()
     or receipt.consumed_at is not null
     or receipt.expires_at <= now() then
    raise exception 'COMMUNITY_UPLOAD_RECEIPT_INVALID';
  end if;
  select * into post_record
  from public.posts where id = receipt.post_id
  for update;
  if post_record.id is null
     or post_record.author_id <> current_profile_id
     or post_record.status <> 'pending_review'
     or p_sort_order < 0
     or p_sort_order >= coalesce(post_record.expected_image_count, 0) then
    raise exception 'COMMUNITY_IMAGE_COUNT_MISMATCH';
  end if;

  insert into public.post_images (
    id, post_id, path, thumbnail_path, sort_order, width, height,
    thumbnail_width, thumbnail_height, full_width, full_height, created_at
  ) values (
    coalesce(p_image_id, gen_random_uuid()),
    receipt.post_id,
    receipt.full_path,
    receipt.thumbnail_path,
    p_sort_order,
    receipt.full_width,
    receipt.full_height,
    receipt.thumbnail_width,
    receipt.thumbnail_height,
    receipt.full_width,
    receipt.full_height,
    now()
  )
  returning * into image_record;

  update private.community_upload_receipts set consumed_at = now() where id = receipt.id;
  select count(*)::integer into attached_image_count
  from public.post_images where post_id = receipt.post_id;
  if attached_image_count > coalesce(post_record.expected_image_count, 0) then
    raise exception 'COMMUNITY_IMAGE_COUNT_MISMATCH';
  end if;
  perform private.try_publish_community_post_media_v1(receipt.post_id);
  return image_record;
end;
$function$

CREATE OR REPLACE FUNCTION public.block_community_user(p_blocked_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  current_profile_id uuid := public.current_community_profile_id();
begin
  if current_profile_id is null then
    raise exception 'COMMUNITY_PROFILE_REQUIRED';
  end if;

  if p_blocked_id is null or not exists (select 1 from public.profiles where id = p_blocked_id) then
    raise exception 'COMMUNITY_BLOCK_TARGET_NOT_FOUND';
  end if;

  if p_blocked_id = current_profile_id then
    raise exception 'COMMUNITY_CANNOT_BLOCK_SELF';
  end if;

  insert into public.community_blocks (blocker_id, blocked_id, reason, created_at)
  values (current_profile_id, p_blocked_id, nullif(btrim(coalesce(p_reason, '')), ''), now())
  on conflict (blocker_id, blocked_id)
  do update set
    reason = excluded.reason,
    created_at = excluded.created_at;
end;
$function$

