CREATE OR REPLACE FUNCTION public.community_contains_objectionable_text(target_text text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  normalized text := lower(coalesce(target_text, ''));
  pattern text;
  patterns text[] := array[
    '约炮', '裸聊', '黄片', '色情', '卖淫', '嫖娼', '援交',
    '开盒', '人肉搜索', '身份证号', '去死', '弄死', '杀了你',
    '自杀教程', '炸弹', '恐怖袭击', '毒品', '大麻', '冰毒',
    'fuck', 'porn', 'nude', 'kill yourself', 'terrorist', 'bomb',
    'doxx', 'doxxing', 'drug dealer'
  ];
begin
  foreach pattern in array patterns loop
    if normalized like '%' || pattern || '%' then
      return true;
    end if;
  end loop;

  return false;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_community_comment_v1(p_id uuid, p_post_id uuid, p_body text, p_is_anonymous boolean DEFAULT false)
 RETURNS comments
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  current_profile_id uuid := public.current_community_profile_id();
  created_comment public.comments%rowtype;
begin
  if current_profile_id is null then
    raise exception 'COMMUNITY_PROFILE_REQUIRED';
  end if;

  if not exists (
    select 1 from public.profiles
    where id = current_profile_id
      and community_access_status = 'approved'
      and community_campus_id = public.current_profile_campus_id()
      and is_profile_complete = true
      and nullif(btrim(nickname), '') is not null
  ) then
    raise exception 'PROFILE_COMPLETION_REQUIRED';
  end if;

  if not public.has_accepted_community_terms(public.community_latest_terms_version()) then
    raise exception 'COMMUNITY_TERMS_REQUIRED';
  end if;

  if not exists (
    select 1 from public.posts
    where id = p_post_id
      and campus_id = public.current_profile_campus_id()
      and status = 'published'
  ) then
    raise exception 'COMMUNITY_POST_NOT_FOUND';
  end if;

  insert into public.comments (
    id,
    post_id,
    author_id,
    body,
    is_anonymous,
    status,
    created_at,
    updated_at
  ) values (
    coalesce(p_id, gen_random_uuid()),
    p_post_id,
    current_profile_id,
    btrim(coalesce(p_body, '')),
    coalesce(p_is_anonymous, false),
    'published',
    now(),
    now()
  )
  returning * into created_comment;

  return created_comment;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_community_comment_v2(p_id uuid, p_post_id uuid, p_body text, p_parent_comment_id uuid DEFAULT NULL::uuid, p_reply_to_comment_id uuid DEFAULT NULL::uuid, p_is_anonymous boolean DEFAULT false)
 RETURNS comments
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  current_profile_id uuid := public.current_community_profile_id();
  current_campus_id text := public.current_profile_campus_id();
  created_comment public.comments%rowtype;
  target_post public.posts%rowtype;
  parent_comment public.comments%rowtype;
  reply_target public.comments%rowtype;
  recipient_id uuid;
  actor_name text;
  normalized_body text := btrim(coalesce(p_body, ''));
begin
  if current_profile_id is null or current_campus_id is null then
    raise exception 'COMMUNITY_PROFILE_REQUIRED';
  end if;
  if char_length(normalized_body) not between 1 and 2000 then
    raise exception 'COMMUNITY_COMMENT_BODY_INVALID' using errcode = '22023';
  end if;
  if not exists (
    select 1 from public.profiles
    where id = current_profile_id
      and community_access_status = 'approved'
      and community_campus_id = current_campus_id
      and is_profile_complete = true
      and nullif(btrim(nickname), '') is not null
  ) then
    raise exception 'PROFILE_COMPLETION_REQUIRED';
  end if;
  if not public.has_accepted_community_terms(public.community_latest_terms_version()) then
    raise exception 'COMMUNITY_TERMS_REQUIRED';
  end if;

  select * into target_post
  from public.posts
  where id = p_post_id
    and campus_id = current_campus_id
    and status = 'published';
  if target_post.id is null then
    raise exception 'COMMUNITY_POST_NOT_FOUND';
  end if;

  if (p_parent_comment_id is null) <> (p_reply_to_comment_id is null) then
    raise exception 'COMMUNITY_REPLY_TARGET_INVALID' using errcode = '22023';
  end if;

  if p_parent_comment_id is not null then
    select * into parent_comment
    from public.comments
    where id = p_parent_comment_id
      and post_id = p_post_id
      and parent_comment_id is null
      and status = 'published';

    select * into reply_target
    from public.comments
    where id = p_reply_to_comment_id
      and post_id = p_post_id
      and status = 'published';

    if parent_comment.id is null
       or reply_target.id is null
       or (reply_target.id <> parent_comment.id
           and reply_target.parent_comment_id is distinct from parent_comment.id) then
      raise exception 'COMMUNITY_REPLY_TARGET_INVALID' using errcode = '22023';
    end if;
    recipient_id := reply_target.author_id;
  else
    recipient_id := target_post.author_id;
  end if;

  insert into public.comments (
    id, post_id, author_id, body, is_anonymous, status,
    parent_comment_id, reply_to_comment_id, like_count, created_at, updated_at
  ) values (
    coalesce(p_id, gen_random_uuid()),
    p_post_id,
    current_profile_id,
    normalized_body,
    coalesce(p_is_anonymous, false),
    'published',
    p_parent_comment_id,
    p_reply_to_comment_id,
    0,
    now(),
    now()
  )
  returning * into created_comment;

  select coalesce(nullif(btrim(display_name), ''), nullif(btrim(nickname), ''), '同学')
  into actor_name
  from public.profiles
  where id = current_profile_id;

  perform private.insert_community_interaction_notification_v1(
    recipient_id,
    current_profile_id,
    p_post_id,
    created_comment.id,
    'comment',
    case
      when p_parent_comment_id is null then actor_name || ' 回复了你的帖子'
      else actor_name || ' 回复了你的评论'
    end,
    left(normalized_body, 120)
  );

  return created_comment;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_community_comment_v2(p_id uuid, p_post_id uuid, p_body text, p_parent_comment_id uuid, p_reply_to_comment_id uuid, p_is_anonymous boolean, p_request_id uuid)
 RETURNS comments
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  current_profile_id uuid := public.current_community_profile_id();
  request_payload jsonb;
  previous_request private.community_create_requests%rowtype;
  created_comment public.comments%rowtype;
begin
  if current_profile_id is null then
    raise exception 'COMMUNITY_PROFILE_REQUIRED';
  end if;
  if p_request_id is null then
    raise exception 'COMMUNITY_COMMENT_REQUEST_INVALID' using errcode = '22023';
  end if;

  request_payload := jsonb_build_object(
    'post_id', p_post_id,
    'body', btrim(coalesce(p_body, '')),
    'parent_comment_id', p_parent_comment_id,
    'reply_to_comment_id', p_reply_to_comment_id,
    'is_anonymous', coalesce(p_is_anonymous, false)
  );
  perform pg_advisory_xact_lock(hashtextextended(current_profile_id::text || ':request:' || p_request_id::text, 0));

  select * into previous_request
  from private.community_create_requests
  where actor_id = current_profile_id and request_id = p_request_id;

  if previous_request.request_id is not null then
    if previous_request.mutation_kind <> 'comment'
       or previous_request.request_payload <> request_payload then
      raise exception 'COMMUNITY_CREATE_REQUEST_REUSED' using errcode = '22023';
    end if;
    select * into created_comment from public.comments where id = previous_request.resource_id;
    if created_comment.id is null then
      raise exception 'COMMUNITY_CREATE_REQUEST_RESULT_MISSING';
    end if;
    return created_comment;
  end if;

  created_comment := public.create_community_comment_v2(
    p_id, p_post_id, p_body, p_parent_comment_id,
    p_reply_to_comment_id, p_is_anonymous
  );
  insert into private.community_create_requests (
    actor_id, request_id, mutation_kind, resource_id, request_payload
  ) values (
    current_profile_id, p_request_id, 'comment', created_comment.id, request_payload
  );
  return created_comment;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_community_notification(p_recipient_id uuid, p_actor_id uuid, p_post_id uuid, p_comment_id uuid, p_type text, p_title text, p_body text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  created_notification_id uuid;
  recipient_muted boolean;
begin
  if auth.uid() is null then
    raise exception 'missing authenticated user';
  end if;

  if not public.can_use_profile(p_actor_id) then
    raise exception 'actor profile is not owned by current user';
  end if;

  if p_recipient_id = p_actor_id then
    return null;
  end if;

  if p_type not in ('comment', 'like') then
    raise exception 'invalid notification type';
  end if;

  if nullif(btrim(p_title), '') is null then
    raise exception 'notification title is required';
  end if;

  if not exists (
    select 1
    from public.posts
    where posts.id = p_post_id
      and posts.author_id = p_recipient_id
      and posts.status = 'published'
  ) then
    raise exception 'target post is not available';
  end if;

  if p_comment_id is not null and not exists (
    select 1
    from public.comments
    where comments.id = p_comment_id
      and comments.post_id = p_post_id
      and comments.author_id = p_actor_id
      and comments.status = 'published'
  ) then
    raise exception 'target comment is not available';
  end if;

  select coalesce(settings.muted_all, false)
  into recipient_muted
  from public.community_notification_settings settings
  where settings.user_id = p_recipient_id;

  if coalesce(recipient_muted, false) then
    return null;
  end if;

  insert into public.community_notifications (
    recipient_id,
    actor_id,
    post_id,
    comment_id,
    type,
    title,
    body
  )
  values (
    p_recipient_id,
    p_actor_id,
    p_post_id,
    p_comment_id,
    p_type,
    btrim(p_title),
    nullif(btrim(coalesce(p_body, '')), '')
  )
  returning id into created_notification_id;

  return created_notification_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_community_post_v4(p_id uuid, p_title text, p_body text, p_category text DEFAULT NULL::text, p_is_anonymous boolean DEFAULT false, p_image_count integer DEFAULT 0, p_attachment_count integer DEFAULT 0)
 RETURNS posts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  current_profile_id uuid := public.current_community_profile_id();
  created_post public.posts%rowtype;
begin
  if current_profile_id is null then
    raise exception 'COMMUNITY_PROFILE_REQUIRED';
  end if;
  if p_id is null then
    raise exception 'COMMUNITY_POST_REQUEST_INVALID' using errcode = '22023';
  end if;
  if p_image_count is null or p_image_count < 0 or p_image_count > 4
     or p_attachment_count is null or p_attachment_count < 0 or p_attachment_count > 2 then
    raise exception 'COMMUNITY_MEDIA_COUNT_INVALID' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(current_profile_id::text || ':post:' || p_id::text, 0));

  select * into created_post
  from public.posts
  where id = p_id;

  if created_post.id is not null then
    if created_post.author_id <> current_profile_id
       or created_post.title <> btrim(coalesce(p_title, ''))
       or created_post.body <> btrim(coalesce(p_body, ''))
       or created_post.category is distinct from nullif(btrim(coalesce(p_category, '')), '')
       or created_post.is_anonymous <> coalesce(p_is_anonymous, false)
       or created_post.expected_image_count is distinct from p_image_count
       or coalesce(created_post.expected_attachment_count, 0) <> p_attachment_count then
      raise exception 'COMMUNITY_POST_REQUEST_REUSED' using errcode = '22023';
    end if;
    return created_post;
  end if;

  created_post := public.create_community_post_v2(
    p_id,
    p_title,
    p_body,
    p_category,
    p_is_anonymous,
    p_image_count + p_attachment_count > 0
  );

  update public.posts
  set
    expected_image_count = p_image_count,
    expected_attachment_count = p_attachment_count,
    image_upload_completed_at = case when p_image_count = 0 then now() else null end,
    attachment_upload_completed_at = case when p_attachment_count = 0 then now() else null end
  where id = created_post.id
  returning * into created_post;
  return created_post;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_community_post_v4(p_id uuid, p_title text, p_body text, p_category text, p_is_anonymous boolean, p_image_count integer, p_attachment_count integer, p_request_id uuid)
 RETURNS posts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  current_profile_id uuid := public.current_community_profile_id();
  request_payload jsonb;
  previous_request private.community_create_requests%rowtype;
  created_post public.posts%rowtype;
begin
  if current_profile_id is null then
    raise exception 'COMMUNITY_PROFILE_REQUIRED';
  end if;
  if p_request_id is null then
    raise exception 'COMMUNITY_POST_REQUEST_INVALID' using errcode = '22023';
  end if;

  request_payload := jsonb_build_object(
    'post_id', p_id,
    'title', btrim(coalesce(p_title, '')),
    'body', btrim(coalesce(p_body, '')),
    'category', nullif(btrim(coalesce(p_category, '')), ''),
    'is_anonymous', coalesce(p_is_anonymous, false),
    'image_count', p_image_count,
    'attachment_count', p_attachment_count
  );
  perform pg_advisory_xact_lock(hashtextextended(current_profile_id::text || ':request:' || p_request_id::text, 0));

  select * into previous_request
  from private.community_create_requests
  where actor_id = current_profile_id and request_id = p_request_id;

  if previous_request.request_id is not null then
    if previous_request.mutation_kind <> 'post'
       or previous_request.request_payload <> request_payload then
      raise exception 'COMMUNITY_CREATE_REQUEST_REUSED' using errcode = '22023';
    end if;
    select * into created_post from public.posts where id = previous_request.resource_id;
    if created_post.id is null then
      raise exception 'COMMUNITY_CREATE_REQUEST_RESULT_MISSING';
    end if;
    return created_post;
  end if;

  created_post := public.create_community_post_v4(
    p_id, p_title, p_body, p_category, p_is_anonymous,
    p_image_count, p_attachment_count
  );
  insert into private.community_create_requests (
    actor_id, request_id, mutation_kind, resource_id, request_payload
  ) values (
    current_profile_id, p_request_id, 'post', created_post.id, request_payload
  );
  return created_post;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_timetable_invite(p_code text)
 RETURNS TABLE(id uuid, owner_id uuid, semester_id text, expires_at timestamp with time zone, accepted_by uuid, accepted_at timestamp with time zone, created_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  actor_profile_id uuid;
  actor_campus_id text;
  normalized_code text;
  target_snapshot public.timetable_snapshots%rowtype;
  created_invite public.timetable_invites%rowtype;
begin
  actor_profile_id := public.current_profile_id();
  actor_campus_id := public.current_profile_campus_id();
  if actor_profile_id is null or actor_campus_id is null then
    raise exception 'MISSING_PROFILE';
  end if;

  select *
  into target_snapshot
  from public.timetable_snapshots snapshots
  where snapshots.owner_id = actor_profile_id
    and snapshots.campus_id = actor_campus_id
  order by snapshots.published_at desc
  limit 1;

  if target_snapshot.id is null then
    raise exception 'TIMETABLE_NOT_PUBLISHED';
  end if;

  normalized_code := public.normalize_timetable_invite_code(p_code);
  if char_length(normalized_code) <> 12 then
    raise exception 'INVALID_INVITE_CODE';
  end if;

  insert into public.timetable_invites (
    campus_id,
    owner_id,
    semester_id,
    code_hash,
    expires_at
  )
  values (
    actor_campus_id,
    actor_profile_id,
    target_snapshot.semester_id,
    public.hash_timetable_invite_code(normalized_code),
    now() + interval '7 days'
  )
  returning * into created_invite;

  return query
  select
    created_invite.id,
    created_invite.owner_id,
    created_invite.semester_id,
    created_invite.expires_at,
    created_invite.accepted_by,
    created_invite.accepted_at,
    created_invite.created_at;
exception
  when unique_violation then
    raise exception 'INVITE_CODE_COLLISION';
end;
$function$

CREATE OR REPLACE FUNCTION public.current_community_profile_id()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  linked_profile_id uuid;
begin
  if auth.uid() is null then
    return null;
  end if;

  select profile_id
  into linked_profile_id
  from public.profile_auth_links
  where auth_user_id = auth.uid()
  limit 1;

  return coalesce(linked_profile_id, auth.uid());
end;
$function$

CREATE OR REPLACE FUNCTION public.edge_claim_community_identity(p_auth_user_id uuid, p_campus_id text, p_edu_id text, p_display_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  normalized_campus_id text := coalesce(
    lower(nullif(btrim(coalesce(p_campus_id, '')), '')),
    'bjfu'
  );
  normalized_edu_id text := nullif(btrim(coalesce(p_edu_id, '')), '');
  normalized_display_name text := nullif(btrim(coalesce(p_display_name, '')), '');
  target_profile public.profiles%rowtype;
  is_new_user boolean := false;
begin
  if p_auth_user_id is null or not exists (select 1 from auth.users where id = p_auth_user_id) then
    raise exception 'COMMUNITY_AUTH_SESSION_REQUIRED';
  end if;

  if normalized_campus_id not in ('bjfu', 'general') then
    normalized_campus_id := 'general';
  end if;

  if normalized_edu_id is null then
    raise exception 'COMMUNITY_EDU_ID_REQUIRED';
  end if;

  normalized_display_name := coalesce(normalized_display_name, normalized_edu_id);

  -- Serialize first use across devices. The unique profile identity index is
  -- the final invariant; the lock avoids turning expected concurrency into an
  -- opaque unique-violation response.
  perform pg_advisory_xact_lock(
    hashtextextended(normalized_campus_id || ':' || normalized_edu_id, 0)
  );

  select * into target_profile
  from public.profiles
  where campus_id = normalized_campus_id
    and edu_id = normalized_edu_id;

  if not found then
    insert into public.profiles (
      campus_id,
      edu_id,
      nickname,
      display_name,
      community_campus_id,
      community_access_status,
      community_school_name,
      community_rejection_reason,
      is_profile_complete
    )
    values (
      normalized_campus_id,
      normalized_edu_id,
      '',
      normalized_display_name,
      case when normalized_campus_id = 'bjfu' then 'bjfu' else null end,
      case when normalized_campus_id = 'bjfu' then 'approved' else 'general' end,
      case when normalized_campus_id = 'bjfu' then '北京林业大学' else null end,
      null,
      false
    )
    returning * into target_profile;

    is_new_user := true;
  end if;

  -- One Auth user identifies at most one profile. Switching the local school
  -- account moves only this device link; it never mutates either profile or
  -- any content owned by those profiles.
  insert into public.profile_auth_links (
    auth_user_id,
    profile_id,
    campus_id,
    edu_id,
    last_seen_at
  )
  values (
    p_auth_user_id,
    target_profile.id,
    normalized_campus_id,
    normalized_edu_id,
    now()
  )
  on conflict (auth_user_id) do update
  set
    profile_id = excluded.profile_id,
    campus_id = excluded.campus_id,
    edu_id = excluded.edu_id,
    last_seen_at = excluded.last_seen_at;

  return jsonb_build_object(
    'profile_id', target_profile.id,
    'is_new_user', is_new_user
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.edge_delete_community_account(p_auth_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  target_profile_id uuid;
  target_edu_id text;
begin
  if p_auth_user_id is null then
    raise exception 'COMMUNITY_AUTH_SESSION_REQUIRED';
  end if;

  select links.profile_id, profiles.edu_id
  into target_profile_id, target_edu_id
  from public.profile_auth_links links
  join public.profiles profiles
    on profiles.id = links.profile_id
  where links.auth_user_id = p_auth_user_id;

  if target_profile_id is null then
    return jsonb_build_object(
      'deleted', true,
      'profile_id', null
    );
  end if;

  if lower(btrim(target_edu_id)) = 'review-demo' then
    raise exception 'COMMUNITY_DEMO_ACCOUNT_PROTECTED';
  end if;

  -- Replies written by other users must survive deletion of a root comment.
  -- Detaching them avoids the parent-comment restrict constraint without
  -- deleting another user's content.
  update public.comments replies
  set
    parent_comment_id = null,
    reply_to_comment_id = null,
    updated_at = now()
  where replies.author_id <> target_profile_id
    and replies.parent_comment_id in (
      select roots.id
      from public.comments roots
      where roots.author_id = target_profile_id
    );

  -- These tables intentionally use ON DELETE SET NULL for administrative
  -- workflows. Account deletion removes submissions authored by the user
  -- instead of retaining their text without an owner.
  delete from public.feedback_submissions
  where user_id = target_profile_id;

  delete from public.catalog_suggestions
  where user_id = target_profile_id;

  delete from public.postgraduate_source_suggestions
  where user_id = target_profile_id;

  delete from private.community_identity_link_conflicts
  where auth_user_id = p_auth_user_id
     or profile_id = target_profile_id;

  delete from public.profiles
  where id = target_profile_id;

  return jsonb_build_object(
    'deleted', true,
    'profile_id', target_profile_id
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.edge_record_community_attachment_validation_v1(p_auth_user_id uuid, p_post_id uuid, p_object_path text, p_display_name text, p_content_type text, p_file_extension text, p_byte_size integer, p_sha256 text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  target_profile_id uuid;
  receipt_id uuid;
begin
  select profile_id into target_profile_id
  from public.profile_auth_links
  where auth_user_id = p_auth_user_id;

  if target_profile_id is null then
    raise exception 'COMMUNITY_PROFILE_REQUIRED';
  end if;
  if p_file_extension not in ('pdf', 'xlsx', 'docx', 'md')
     or p_byte_size not between 1 and 10485760
     or p_sha256 !~ '^[0-9a-f]{64}$'
     or char_length(btrim(p_display_name)) not between 1 and 180 then
    raise exception 'COMMUNITY_ATTACHMENT_INVALID';
  end if;
  if not exists (
    select 1 from public.posts
    where id = p_post_id
      and author_id = target_profile_id
      and status = 'pending_review'
      and expected_attachment_count > 0
  ) then
    raise exception 'COMMUNITY_POST_NOT_FOUND';
  end if;
  if p_object_path not like
     'posts/' || target_profile_id::text || '/' || p_post_id::text || '/%' then
    raise exception 'COMMUNITY_UPLOAD_PATH_MISMATCH';
  end if;

  select id into receipt_id
  from private.community_attachment_upload_receipts
  where auth_user_id = p_auth_user_id
    and profile_id = target_profile_id
    and post_id = p_post_id
    and object_path = p_object_path
    and display_name = btrim(p_display_name)
    and content_type = p_content_type
    and file_extension = p_file_extension
    and byte_size = p_byte_size
    and sha256 = p_sha256
    and consumed_at is null
    and expires_at > now()
  limit 1;
  if receipt_id is not null then
    return receipt_id;
  end if;

  insert into private.community_attachment_upload_receipts (
    auth_user_id, profile_id, post_id, object_path, display_name,
    content_type, file_extension, byte_size, sha256
  ) values (
    p_auth_user_id, target_profile_id, p_post_id, p_object_path,
    btrim(p_display_name), p_content_type, p_file_extension, p_byte_size, p_sha256
  )
  returning id into receipt_id;
  return receipt_id;
end;
$function$

