CREATE OR REPLACE FUNCTION public.report_community_content(p_target_type text, p_post_id uuid DEFAULT NULL::uuid, p_comment_id uuid DEFAULT NULL::uuid, p_reported_user_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT '违规内容'::text, p_detail text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  current_profile_id uuid := public.current_community_profile_id();
  target_author_id uuid;
  target_post_id uuid;
  existing_report_id uuid;
  created_report_id uuid;
  normalized_target_type text := lower(nullif(btrim(coalesce(p_target_type, '')), ''));
  normalized_reason text := coalesce(nullif(btrim(p_reason), ''), '违规内容');
  normalized_detail text := nullif(btrim(coalesce(p_detail, '')), '');
begin
  if current_profile_id is null then
    raise exception 'COMMUNITY_PROFILE_REQUIRED';
  end if;

  if (select count(*) from public.community_reports
      where reporter_id = current_profile_id
        and created_at >= now() - interval '24 hours') >= 20 then
    raise exception 'COMMUNITY_REPORT_RATE_LIMIT_EXCEEDED';
  end if;

  if normalized_target_type = 'post' then
    select author_id into target_author_id
    from public.posts
    where id = p_post_id and status <> 'deleted';
    target_post_id := p_post_id;
  elsif normalized_target_type = 'comment' then
    select author_id, post_id into target_author_id, target_post_id
    from public.comments
    where id = p_comment_id and status <> 'deleted';
  elsif normalized_target_type = 'user' then
    target_author_id := p_reported_user_id;
    if target_author_id is not null
       and not exists (select 1 from public.profiles where id = target_author_id) then
      target_author_id := null;
    end if;
  else
    raise exception 'COMMUNITY_INVALID_REPORT_TARGET';
  end if;

  if target_author_id is null then
    raise exception 'COMMUNITY_REPORT_TARGET_NOT_FOUND';
  end if;

  select id into existing_report_id
  from public.community_reports
  where reporter_id = current_profile_id
    and status = 'open'
    and (
      (normalized_target_type = 'post' and target_type = 'post' and post_id = p_post_id)
      or (normalized_target_type = 'comment' and target_type = 'comment' and comment_id = p_comment_id)
      or (normalized_target_type = 'user' and target_type = 'user' and reported_user_id = target_author_id)
    )
  limit 1;

  if existing_report_id is not null then
    return existing_report_id;
  end if;

  insert into public.community_reports (
    reporter_id,
    reported_user_id,
    target_type,
    post_id,
    comment_id,
    reason,
    detail,
    status
  ) values (
    current_profile_id,
    target_author_id,
    normalized_target_type,
    case when normalized_target_type in ('post', 'comment') then target_post_id else null end,
    case when normalized_target_type = 'comment' then p_comment_id else null end,
    normalized_reason,
    normalized_detail,
    'open'
  )
  returning id into created_report_id;

  return created_report_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.revoke_community_terms(p_terms_version text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  current_profile_id uuid := public.current_community_profile_id();
  revoked_version text := coalesce(nullif(btrim(p_terms_version), ''), public.community_latest_terms_version());
begin
  if current_profile_id is null then
    raise exception 'COMMUNITY_PROFILE_REQUIRED';
  end if;

  delete from public.community_terms_acceptances
  where user_id = current_profile_id
    and terms_version = revoked_version;
end;
$function$

CREATE OR REPLACE FUNCTION public.select_community_campus(p_campus_id text)
 RETURNS profiles
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  actor_profile_id uuid := public.current_profile_id();
  actor_auth_user_id uuid := auth.uid();
  normalized_campus_id text := lower(btrim(coalesce(p_campus_id, '')));
  actor_profile public.profiles;
  target_campus public.campuses;
  updated_profile public.profiles;
begin
  perform set_config('app.community_membership_action', 'true', true);

  if actor_auth_user_id is null or actor_profile_id is null then
    raise exception 'COMMUNITY_AUTH_REQUIRED' using errcode = '42501';
  end if;

  if normalized_campus_id = '' or normalized_campus_id in ('general', 'bjfu') then
    raise exception 'COMMUNITY_CAMPUS_NOT_SELECTABLE' using errcode = '22023';
  end if;

  select *
  into actor_profile
  from public.profiles
  where id = actor_profile_id;

  if actor_profile.id is null then
    raise exception 'COMMUNITY_PROFILE_REQUIRED' using errcode = '42501';
  end if;

  if exists (
    select 1
    from public.campus_membership_requests requests
    where requests.requester_profile_id = actor_profile_id
      and requests.status = 'pending'
  ) then
    raise exception 'COMMUNITY_REQUEST_PENDING' using errcode = '23505';
  end if;

  if actor_profile.community_access_status = 'approved'
    and actor_profile.community_campus_id is not null
  then
    raise exception 'COMMUNITY_CAMPUS_ALREADY_SELECTED' using errcode = '23505';
  end if;

  select *
  into target_campus
  from public.campuses
  where id = normalized_campus_id
    and status = 'active'
    and is_community_enabled = true;

  if target_campus.id is null then
    raise exception 'COMMUNITY_CAMPUS_NOT_FOUND' using errcode = '22023';
  end if;

  update public.profiles
  set
    campus_id = target_campus.id,
    community_campus_id = target_campus.id,
    community_access_status = 'approved',
    community_school_name = target_campus.display_name,
    community_rejection_reason = null,
    community_request_id = null,
    updated_at = now()
  where id = actor_profile_id
  returning * into updated_profile;

  update public.profile_auth_links
  set
    campus_id = target_campus.id,
    last_seen_at = now()
  where profile_id = actor_profile_id
    and auth_user_id = actor_auth_user_id;

  return updated_profile;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.soft_delete_own_comment(target_comment_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  affected_count integer;
begin
  if auth.uid() is null then
    raise exception 'missing authenticated user';
  end if;

  update public.comments
  set
    status = 'deleted',
    updated_at = now()
  where id = target_comment_id
    and public.can_use_profile(author_id)
    and status in ('published', 'pending_review', 'hidden');

  get diagnostics affected_count = row_count;

  if affected_count = 0 then
    if exists (
      select 1
      from public.comments
      where id = target_comment_id
        and public.can_use_profile(author_id)
        and status = 'deleted'
    ) then
      return;
    end if;

    raise exception 'comment not found or not owned by current user';
  end if;
end;
$function$

