CREATE OR REPLACE FUNCTION public.submit_campus_membership_request(p_school_name text)
 RETURNS campus_membership_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  actor_profile_id uuid := public.current_profile_id();
  actor_auth_user_id uuid := auth.uid();
  normalized_school_name text := public.normalize_school_name(p_school_name);
  actor_profile public.profiles;
  inserted_request public.campus_membership_requests;
begin
  perform set_config('app.community_membership_action', 'true', true);

  if actor_auth_user_id is null or actor_profile_id is null then
    raise exception 'COMMUNITY_AUTH_REQUIRED' using errcode = '42501';
  end if;

  if normalized_school_name is null or normalized_school_name = '' then
    raise exception 'COMMUNITY_SCHOOL_NAME_REQUIRED' using errcode = '22023';
  end if;

  select *
  into actor_profile
  from public.profiles
  where id = actor_profile_id;

  if actor_profile.id is null then
    raise exception 'COMMUNITY_PROFILE_REQUIRED' using errcode = '42501';
  end if;

  if actor_profile.community_access_status = 'approved'
    and actor_profile.community_campus_id is not null
  then
    raise exception 'COMMUNITY_CAMPUS_ALREADY_SELECTED' using errcode = '23505';
  end if;

  if exists (
    select 1
    from public.campus_membership_requests requests
    where requests.requester_profile_id = actor_profile_id
      and requests.status = 'pending'
  ) then
    raise exception 'COMMUNITY_REQUEST_PENDING' using errcode = '23505';
  end if;

  insert into public.campus_membership_requests (
    requester_profile_id,
    requester_auth_user_id,
    school_name,
    normalized_school_name,
    request_type,
    status
  )
  values (
    actor_profile_id,
    actor_auth_user_id,
    btrim(p_school_name),
    normalized_school_name,
    'initial_new_school',
    'pending'
  )
  returning * into inserted_request;

  update public.profiles
  set
    campus_id = 'general',
    community_campus_id = null,
    community_access_status = 'pending',
    community_school_name = inserted_request.school_name,
    community_rejection_reason = null,
    community_request_id = inserted_request.id,
    updated_at = now()
  where id = actor_profile_id;

  update public.profile_auth_links
  set
    campus_id = 'general',
    last_seen_at = now()
  where profile_id = actor_profile_id
    and auth_user_id = actor_auth_user_id;

  return inserted_request;
end;
$function$

CREATE OR REPLACE FUNCTION public.submit_community_school_change_request(p_campus_id text)
 RETURNS campus_membership_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  actor_profile_id uuid := public.current_profile_id();
  actor_auth_user_id uuid := auth.uid();
  normalized_campus_id text := lower(btrim(coalesce(p_campus_id, '')));
  actor_profile public.profiles;
  target_campus public.campuses;
  inserted_request public.campus_membership_requests;
begin
  perform set_config('app.community_membership_action', 'true', true);

  if actor_auth_user_id is null or actor_profile_id is null then
    raise exception 'COMMUNITY_AUTH_REQUIRED' using errcode = '42501';
  end if;

  if normalized_campus_id = '' or normalized_campus_id in ('general', 'bjfu') then
    raise exception 'COMMUNITY_CAMPUS_NOT_SELECTABLE' using errcode = '22023';
  end if;

  select *
  into actor_profile
  from public.profiles
  where id = actor_profile_id;

  if actor_profile.id is null
    or actor_profile.community_access_status is distinct from 'approved'
    or actor_profile.community_campus_id is null
  then
    raise exception 'COMMUNITY_APPROVED_CAMPUS_REQUIRED' using errcode = '42501';
  end if;

  if actor_profile.community_campus_id = normalized_campus_id then
    raise exception 'COMMUNITY_CAMPUS_UNCHANGED' using errcode = '22023';
  end if;

  if exists (
    select 1
    from public.campus_membership_requests requests
    where requests.requester_profile_id = actor_profile_id
      and requests.status = 'pending'
  ) then
    raise exception 'COMMUNITY_REQUEST_PENDING' using errcode = '23505';
  end if;

  select *
  into target_campus
  from public.campuses
  where id = normalized_campus_id
    and status = 'active'
    and is_community_enabled = true;

  if target_campus.id is null then
    raise exception 'COMMUNITY_CAMPUS_NOT_FOUND' using errcode = '22023';
  end if;

  insert into public.campus_membership_requests (
    requester_profile_id,
    requester_auth_user_id,
    school_name,
    normalized_school_name,
    request_type,
    requested_campus_id,
    from_campus_id,
    status
  )
  values (
    actor_profile_id,
    actor_auth_user_id,
    target_campus.display_name,
    target_campus.normalized_name,
    'school_change',
    target_campus.id,
    actor_profile.community_campus_id,
    'pending'
  )
  returning * into inserted_request;

  update public.profiles
  set
    community_request_id = inserted_request.id,
    community_rejection_reason = null,
    updated_at = now()
  where id = actor_profile_id;

  return inserted_request;
end;
$function$

CREATE OR REPLACE FUNCTION public.toggle_community_comment_like_v1(p_comment_id uuid, p_request_id uuid)
 RETURNS TABLE(comment_id uuid, like_count integer, viewer_has_liked boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  current_profile_id uuid := public.current_community_profile_id();
  target_comment public.comments%rowtype;
  target_post public.posts%rowtype;
  did_like boolean;
  actor_name text;
  previous_request private.community_comment_like_requests%rowtype;
begin
  if current_profile_id is null then
    raise exception 'COMMUNITY_PROFILE_REQUIRED';
  end if;
  if p_request_id is null then
    raise exception 'COMMUNITY_LIKE_REQUEST_INVALID' using errcode = '22023';
  end if;
  if not public.has_accepted_community_terms(public.community_latest_terms_version()) then
    raise exception 'COMMUNITY_TERMS_REQUIRED';
  end if;

  select * into target_comment
  from public.comments
  where id = p_comment_id and status = 'published'
  for update;
  if target_comment.id is null then
    raise exception 'COMMUNITY_COMMENT_NOT_FOUND';
  end if;

  select * into previous_request
  from private.community_comment_like_requests
  where request_id = p_request_id and user_id = current_profile_id;
  if previous_request.request_id is not null then
    if previous_request.comment_id <> p_comment_id then
      raise exception 'COMMUNITY_LIKE_REQUEST_REUSED' using errcode = '22023';
    end if;
    return query
    select
      previous_request.comment_id,
      previous_request.like_count,
      previous_request.viewer_has_liked;
    return;
  end if;

  select * into target_post
  from public.posts
  where id = target_comment.post_id
    and status = 'published'
    and campus_id = public.current_profile_campus_id();
  if target_post.id is null then
    raise exception 'COMMUNITY_COMMENT_NOT_FOUND';
  end if;
  if target_comment.author_id = current_profile_id then
    raise exception 'COMMUNITY_COMMENT_SELF_LIKE_FORBIDDEN';
  end if;

  if exists (
    select 1 from public.comment_likes
    where comment_likes.comment_id = p_comment_id
      and user_id = current_profile_id
  ) then
    delete from public.comment_likes
    where comment_likes.comment_id = p_comment_id
      and user_id = current_profile_id;
    did_like := false;
  else
    insert into public.comment_likes (comment_id, user_id)
    values (p_comment_id, current_profile_id);
    did_like := true;
  end if;

  if did_like then
    select coalesce(nullif(btrim(display_name), ''), nullif(btrim(nickname), ''), '同学')
    into actor_name
    from public.profiles
    where id = current_profile_id;
    perform private.insert_community_interaction_notification_v1(
      target_comment.author_id,
      current_profile_id,
      target_comment.post_id,
      target_comment.id,
      'like',
      actor_name || ' 点赞了你的评论',
      left(target_comment.body, 120)
    );
  end if;

  insert into private.community_comment_like_requests (
    request_id, user_id, comment_id, like_count, viewer_has_liked
  )
  select
    p_request_id,
    current_profile_id,
    target_comment.id,
    comments.like_count,
    did_like
  from public.comments
  where comments.id = target_comment.id;

  return query
  select
    target_comment.id,
    comments.like_count,
    did_like
  from public.comments
  where comments.id = target_comment.id;
end;
$function$
